contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entrypoint for the property test
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        bytes32[] calldata proofProof,
        bool[] calldata proofFlags,
        uint256 ethAmount
    ) public payable {
        // ensure we can forward ETH if needed
        require(address(this).balance >= ethAmount, "insufficient balance to send");

        // read observable before-state
        uint256 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint256 beforeVirtualNft = c.virtualNftReserves();
        address poolNft = c.nft();
        address poolBase = c.baseToken();

        C.MerkleMultiProof memory proof;
        proof.proof = proofProof;
        proof.flags = proofFlags;

        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // perform call with ETH forwarded if baseToken==address(0)
        if (poolBase == address(0)) {
            // call payable buy
            try c.buy{value: ethAmount}(tokenIds, tokenWeights, proof) returns (uint256 n, uint256 f, uint256 p) {
                reverted = false;
                netInputAmount = n; feeAmount = f; protocolFeeAmount = p;
            } catch {
                reverted = true;
            }
        } else {
            // no ETH should be sent when baseToken != address(0)
            try c.buy(tokenIds, tokenWeights, proof) returns (uint256 n, uint256 f, uint256 p) {
                reverted = false;
                netInputAmount = n; feeAmount = f; protocolFeeAmount = p;
            } catch {
                reverted = true;
            }
        }

        // Observables after
        uint256 afterVirtualBase = c.virtualBaseTokenReserves();
        uint256 afterVirtualNft = c.virtualNftReserves();

        // Check: if the call succeeded, the virtualNftReserves must have decreased by sum(tokenWeights),
        // and virtualBaseTokenReserves must have increased by (netInputAmount - feeAmount - protocolFeeAmount).
        // If the call reverted, then at least one of: merkle root check failed (we cannot observe directly),
        // or for ETH pools msg.value < netInputAmount (caller didn't send enough). We capture that by
        // requiring that if it reverted and pool uses ETH then ethAmount < netInputAmount (unobservable) cannot be used;
        // Instead we assert a conservative general invariant:
        //   Either the call reverted, or afterVirtualNft + sum(weights) == beforeVirtualNft and
        //   afterVirtualBase == beforeVirtualBase + (netInputAmount - feeAmount - protocolFeeAmount).

        // compute sum of weights (safe to compute in test)
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // final single assert rule
        assert(
            reverted || (
                afterVirtualNft + sumWeights == beforeVirtualNft &&
                // avoid underflow: netInputAmount >= feeAmount + protocolFeeAmount by design of buyQuote
                (afterVirtualBase == beforeVirtualBase + (netInputAmount - feeAmount - protocolFeeAmount))
            )
        );
    }

    receive() external payable {}
}

