contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public test entry point: attempts to call buy and then asserts the observable invariant
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proof, bool[] calldata flags, uint256 ethAmount) public payable {
        // build MerkleMultiProof calldata struct compatible with c.sumWeightsAndValidateProof / buy
        // The C.buy takes a MerkleMultiProof calldata; create a memory struct by copying calldata
        C.MerkleMultiProof memory mp = C.MerkleMultiProof({ proof: new bytes32[](proof.length), flags: new bool[](flags.length) });
        for (uint256 i = 0; i < proof.length; i++) mp.proof[i] = proof[i];
        for (uint256 i = 0; i < flags.length; i++) mp.flags[i] = flags[i];

        // record before-values via public getters
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNft = c.virtualNftReserves();
        uint256 beforeBalance = address(c).balance;

        // ensure this contract has enough ETH to forward if needed
        if (ethAmount > 0) {
            require(address(this).balance >= ethAmount, "no-eth");
        }

        // perform the call, capturing revert state and returned values if any
        bool reverted = false;
        uint256 netInputAmount = 0;
        uint256 feeAmount = 0;
        uint256 protocolFeeAmount = 0;

        // We cannot call c.buy directly with calldata structs from here; must use try/catch to capture revert.
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, mp) returns (uint256 n, uint256 f, uint256 p) {
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // read after-values
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();
        uint256 afterBalance = address(c).balance;

        // compute sum of weights (observable by us since we have tokenWeights input)
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // General rule:
        // If the call reverted, then either the provided ETH amount was insufficient/invalid for native-base pools
        // or some other requirement failed; we assert that no state changes occurred to virtual reserves observed
