contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept calldata for a buy: tokenIds and tokenWeights arrays, plus merkle proof components and an ETH amount to send.
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        bytes32[] calldata proofProof,
        bool[] calldata proofFlags,
        uint256 ethAmount
    ) public payable {
        // ensure we have enough balance to forward ETH if needed
        require(address(this).balance >= ethAmount, "not enough balance");

        // observe pre-state via public getters
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNft = c.virtualNftReserves();
        address baseToken = c.baseToken();

        // prepare MerkleMultiProof struct in memory to pass to buy
        C.MerkleMultiProof memory mp;
        mp.proof = new bytes32[](proofProof.length);
        for (uint i = 0; i < proofProof.length; i++) mp.proof[i] = proofProof[i];
        mp.flags = new bool[](proofFlags.length);
        for (uint i = 0; i < proofFlags.length; i++) mp.flags[i] = proofFlags[i];

        // try the buy call and capture revert status and returned values if any
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, mp) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // observe post-state
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();

        // compute sum of weights (we may read via sumWeightsAndValidateProof view to get the canonical sum)
        uint256 weightSum;
        try c.sumWeightsAndValidateProof(tokenIds, tokenWeights, mp) returns (uint256 s) {
            weightSum = s;
        } catch {
            // if proof invalid, sumWeights reverts; set to an impossible large number to avoid matching the expected delta
            weightSum = type(uint256).max;
        }

        // General invariant: if the buy call succeeded (did not revert) then virtualBaseTokenReserves increased by exactly (netInputAmount - feeAmount - protocolFeeAmount)
        // and virtualNftReserves decreased by exactly weightSum. If buy reverted, there's no requirement.
        if (!reverted) {
            // Avoid under/overflow in expressions by using comparisons rewritten as equalities rearranged into allowed operations
            // Check base reserves increased by netInputAmount - feeAmount - protocolFeeAmount
            uint256 expectedBaseIncrease = netInputAmount - feeAmount - protocolFeeAmount;
            // cast uint128 to uint256 for comparison
            bool baseOk = (uint256(afterVirtualBase) == uint256(beforeVirtualBase) + expectedBaseIncrease);
            bool nftOk = (uint256(afterVirtualNft) + weightSum == uint256(beforeVirtualNft));
