contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We test the behavior of change(...): when input weight sum < output weight sum it must revert;
    // otherwise it must not revert and the number of output tokenIds transferred to caller equals
    // outputTokenIds.length and input tokenIds transferred from caller equals inputTokenIds.length.
    // Because we cannot observe internal NFT transfers directly, we instead assert that when the call
    // succeeds, the returned (feeAmount, protocolFeeAmount) match the public view changeFeeQuote for
    // the computed inputWeightSum and that feeAmount >= 0 (always true) and protocolFeeAmount >= 0.

    // Note: to send Ether with the call, pass etherAmount and ensure this contract has enough balance.
    function run(
        uint256[] calldata inputTokenIds,
        uint256[] calldata inputTokenWeights,
        bytes calldata inputProofPacked, // abi.encode(MerkleMultiProof)
        IStolenNftOracle.Message[] calldata stolenNftProofs,
        uint256[] calldata outputTokenIds,
        uint256[] calldata outputTokenWeights,
        bytes calldata outputProofPacked,
        uint256 etherAmount
    ) public payable {
        require(true); // no extra preconditions

        // Recover MerkleMultiProof structs from packed calldata blobs (decoder in-place)
        // We cannot allocate dynamic calldata structs easily; instead we will treat the packed bytes
        // as either empty (length 0) meaning merkleRoot==0 case, or as some non-empty bytes that
        // will likely fail proof verification if not correct. The contract under test will revert
        // on invalid proofs; our property handles both revert and success cases.

        // Ensure we have ether to forward if requested
        if (etherAmount > 0) {
            require(address(this).balance >= etherAmount, "no ether");
        }

        bool reverted;
        uint256 feeAmountReturned = 0;
        uint256 protocolFeeAmountReturned = 0;

        // We need to call c.change which is state-changing and must be a top-level statement.
        // Because change has complex calldata types (MerkleMultiProof), we synthesize minimal
        // compatible arguments: decode inputProofPacked/outputProofPacked expecting abi.encode(
        // bytes32[] proof, bool[] flags ). We'll attempt a low-level call to avoid solidity decoding
        // issues; but per constraints we must call c.change as a top-level call. We'll call via
        // c.change(...) directly using empty proofs when packed length==0, else pass empty proofs too.
        // This keeps behavior deterministic: if merkleRoot is zero, sumWeightsAndValidateProof will
        // accept and return default weights; otherwise invalid proof will cause revert which we capture.

        // Build empty MerkleMultiProof values in memory for both input and output.
        C.MerkleMultiProof memory emptyProof;
        bytes memory emptyProofEncoded = abi.encode(emptyProof);

        // If caller wanted to forward ether, we pass it along. We must call top-level; use try/catch to detect revert.
        try c.change{value: etherAmount}(
            inputTokenIds,
            inputTokenWeights,
            emptyProof,
            stolenNftProofs,
            outputTokenIds,
            outputTokenWeights,
            emptyProof
        ) returns (uint256 feeAmt, uint256 protocolFeeAmt) {
            reverted = false;
            feeAmountReturned = feeAmt;
            protocolFeeAmountReturned = protocolFeeAmt;
        } catch {
            reverted = true;
        }

        // Compute input and output weight sums locally to express the property.
        // If merkleRoot == 0 in c, sumWeightsAndValidateProof returns len*1e18 for each side.
        uint256 inputWeightSum = 0;
        for (uint256 i = 0; i < inputTokenWeights.length; i++) {
            inputWeightSum += inputTokenWeights[i];
        }
        uint256 outputWeightSum = 0;
        for (uint256 i = 0; i < outputTokenWeights.length; i++) {
            outputWeightSum += outputTokenWeights[i];
        }

        // General rule asserted:
        // - If inputWeightSum < outputWeightSum then change must revert (InsufficientInputWeight) OR proofs may be invalid causing revert.
        //   We assert that in the case inputWeightSum < outputWeightSum the call did revert.
        // - Otherwise (inputWeightSum >= outputWeightSum) if the call succeeded then returned fees must equal changeFeeQuote(inputWeightSum)
        //   as observable via public view changeFeeQuote. If the call reverted, that is acceptable (e.g., invalid proofs), so we don't require success.

        (uint256 expectedFee, uint256 expectedProtocol) = c.changeFeeQuote(inputWeightSum);

        assert(
            // If input weight insufficient, the change call cannot succeed (must revert)
            (inputWeightSum < outputWeightSum && reverted)
            ||
            // Else if not reverted, the returned fees must equal the view quote
            (inputWeightSum >= outputWeightSum && (!reverted && feeAmountReturned == expectedFee && protocolFeeAmountReturned == expectedProtocol))
        );
    }

    receive() external payable {}
}

